	private static void createPokeParty(global::Pml.PokeParty pPokeParty, global::XLSXContent.TrainerTable.SheetTrainerPoke trainerPoke, global::XLSXContent.TrainerTable.SheetTrainerData trainerData, global::XLSXContent.TrainerTable.SheetTrainerType trainerTypeData, global::Dpr.BallDeco.CapsuleData[] capsuleDatas) {
