	public static global::Pml.PokePara.PokemonParam createPokemon(in global::TrainerSystem.PokeParamForCreate pokeData, global::XLSXContent.TrainerTable.SheetTrainerData trainerData, global::XLSXContent.TrainerTable.SheetTrainerType trainerTypeData, global::Pml.PokeParty pokePartyForRndCheck = null) {
