        if (pokePartyForRndCheck != null)
        {
            // FindPersnalRnd is inlined 7 times (@02cc2854–02cc2b44), each try followed by a fresh NextUInt
            for (int i = 0; i < 7; i++)
            {
                if (!FindPersnalRnd(pokePartyForRndCheck, personal_rand))
                    break;

                personal_rand = random.NextUInt();
            }
        }

        var initSpec = new InitialSpec();
        setupInitSpec(initSpec, pokeData, personal_rand, trainerTypeData.Sex);
        var pp = new PokemonParam(initSpec);
        setupPokemon(pp, pokeData, trainerTypeData, false);
        return pp;
    }
