            if (pp != null && pp.GetPersonalRnd() == personal_rand)
                return true;
        }

        return false;
    }
	private static void setupInitSpec(global::Pml.PokePara.InitialSpec pInitSpec, in global::TrainerSystem.PokeParamForCreate pokeData, ulong personal_rand, byte trainerSex) {
        pInitSpec.personalRnd = personal_rand;
        pInitSpec.monsno = (MonsNo)pokeData.MonsNo;
        pInitSpec.formno = pokeData.FormNo;
        pInitSpec.rareRnd = pokeData.IsRare ? InitialSpec.INIT_SPEC_RARE_TRUE : InitialSpec.INIT_SPEC_RARE_FALSE;
        pInitSpec.id = personal_rand;
        pInitSpec.level = pokeData.Level;
        pInitSpec.seikaku = pokeData.Seikaku;
        pInitSpec.talentPower[0] = pokeData.TalentHp;
        pInitSpec.talentPower[1] = pokeData.TalentAtk;
        pInitSpec.talentPower[2] = pokeData.TalentDef;
        pInitSpec.talentPower[3] = pokeData.TalentSpAtk;
        pInitSpec.talentPower[4] = pokeData.TalentSpDef;
        pInitSpec.talentPower[5] = pokeData.TalentAgi;

        var personalData = Pml.Personal.PersonalSystem.GetPersonalData((MonsNo)pokeData.MonsNo, pokeData.FormNo);
        uint sexRatio = Pml.Personal.PersonalTableExtensions.GetParam(personalData, Pml.Personal.ParamID.SEX);
        if (sexRatio == 0)
        {
            pInitSpec.sex = (ushort)Sex.MALE;
        }
        else if (sexRatio == 0xff)
        {
            pInitSpec.sex = (ushort)Sex.UNKNOWN;
        }
        else if (sexRatio == 0xfe)
        {
            pInitSpec.sex = (ushort)Sex.FEMALE;
        }
        else if (pokeData.Sex == Sex.MALE || pokeData.Sex == Sex.FEMALE)
        {
            pInitSpec.sex = (ushort)pokeData.Sex;
        }
        else if (sexRatio < 0x79)
        {
            pInitSpec.sex = (ushort)Sex.MALE;
        }
        else if (sexRatio > 0x87)
        {
            pInitSpec.sex = (ushort)Sex.FEMALE;
        }
        else
        {
            pInitSpec.sex = trainerSex;
        }

        if (pokeData.TokuseiNo != 0)
        {
            if (personalData.tokusei1 == (ushort)pokeData.TokuseiNo)
            {
                pInitSpec.tokuseiIndex = 0;
            }
            else if (personalData.tokusei2 == (ushort)pokeData.TokuseiNo)
            {
                pInitSpec.tokuseiIndex = 1;
            }
            else if (personalData.tokusei3 == (ushort)pokeData.TokuseiNo)
            {
                pInitSpec.tokuseiIndex = 2;
            }
            else
            {
                GFL.ASSERT(pInitSpec.tokuseiIndex != 0xff, string.Format("{0} is invalid for {1}", pokeData.TokuseiNo, (MonsNo)pokeData.MonsNo));
            }
        }

        if (pInitSpec.tokuseiIndex == 0xff)
            pInitSpec.tokuseiIndex = (byte)((personal_rand >> 16) & 1);
    }
	private static void setupPokemon(global::Pml.PokePara.PokemonParam pPokeParam, in global::TrainerSystem.PokeParamForCreate pokeData, global::XLSXContent.TrainerTable.SheetTrainerType trainerTypeData, bool isApplyPPUp) {
        pPokeParam.SetItem(pokeData.Item);
        pPokeParam.ChangeEffortPower(PowerID.HP, pokeData.EffortHp);
        pPokeParam.ChangeEffortPower(PowerID.ATK, pokeData.EffortAtk);
        pPokeParam.ChangeEffortPower(PowerID.DEF, pokeData.EffortDef);
        pPokeParam.ChangeEffortPower(PowerID.SPATK, pokeData.EffortSpAtk);
        pPokeParam.ChangeEffortPower(PowerID.SPDEF, pokeData.EffortSpDef);
        pPokeParam.ChangeEffortPower(PowerID.AGI, pokeData.EffortAgi);

        BallId ball = pokeData.Ball;
        if (ball == BallId.MAX || ball == BallId.NULL)
            ball = trainerTypeData.BallId;
        if (ball == BallId.MAX || ball == BallId.NULL)
            ball = BallId.MONSUTAABOORU;
        pPokeParam.SetGetBall((uint)ball);

        // setupPokemon_Waza / setupPokemon_WazaPPUp are inlined (@02cc01e0 / @02cc0278, TrainerSystem class-init before each)
        setupPokemon_Waza(pPokeParam, pokeData);
        if (isApplyPPUp)
            setupPokemon_WazaPPUp(pPokeParam);
    }
	private static void setupPokemon_Waza(global::Pml.PokePara.PokemonParam pPokeParam, in global::TrainerSystem.PokeParamForCreate pokeData) {
        if (pokeData.Waza1 == 0 && pokeData.Waza2 == 0 && pokeData.Waza3 == 0 && pokeData.Waza4 == 0)
            return;

        pPokeParam.SetWaza(0, (WazaNo)pokeData.Waza1);
        pPokeParam.SetWaza(1, (WazaNo)pokeData.Waza2);
        pPokeParam.SetWaza(2, (WazaNo)pokeData.Waza3);
        pPokeParam.SetWaza(3, (WazaNo)pokeData.Waza4);
    }
	private static void setupPokemon_WazaPPUp(global::Pml.PokePara.PokemonParam pPokeParam) {
        pPokeParam.SetWazaPPUpCount(0, 3);
        pPokeParam.SetWazaPPUpCount(1, 3);
        pPokeParam.SetWazaPPUpCount(2, 3);
        pPokeParam.SetWazaPPUpCount(3, 3);
        pPokeParam.RecoverWazaPPAll();
    }
	public static global::Dpr.Trainer.TrainerType GetTagTrainerType(global::Dpr.Trainer.TrainerType trtype1, global::Dpr.Trainer.TrainerType trtype2) {
        for (int i = 0; i < TAG_TABLE.Length; i++)
        {
            if ((TAG_TABLE[i].typeA == trtype1 && TAG_TABLE[i].typeB == trtype2) ||
                (TAG_TABLE[i].typeB == trtype1 && TAG_TABLE[i].typeA == trtype2))
            {
                return TAG_TABLE[i].tagType;
            }
        }

        return TrainerType.INVALID;
    }
